// Cliopatria date intervals and lazily decoded, local geometry bundles.
export function binFor(manifest,year){return manifest.bins.find(b=>b.from<=year&&year<=b.to)||null;}
function ring(deltas){let x=0,y=0;return deltas.map(([dx,dy])=>{x+=dx;y+=dy;return [x/1000,y/1000];});}
export function decodeGeometry(g){return {type:g.type,coordinates:g.type==='Polygon'?g.coordinates.map(ring):g.coordinates.map(p=>p.map(ring))};}
export async function unpackBundle(envelope){if(envelope.encoding!=='gzip-base64')throw Error('Unsupported map encoding');const bytes=Uint8Array.from(atob(envelope.data),c=>c.charCodeAt(0));let raw;if(typeof DecompressionStream!=='undefined'){const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));raw=await new Response(stream).text();}else if(globalThis.pako){raw=new TextDecoder().decode(globalThis.pako.ungzip(bytes));}else throw Error('Map decompressor unavailable');return JSON.parse(raw);}
export function featuresAt(bundle,year){const geometries=new Map();return bundle.features.filter(f=>f.properties.from<=year&&year<=f.properties.to).map(f=>{if(!geometries.has(f.geometry))geometries.set(f.geometry,decodeGeometry(bundle.geometries[f.geometry]));return {...f,geometry:geometries.get(f.geometry)};});}
export class PolityStore {
 constructor(manifest,fetcher=url=>globalThis.fetch(url)){this.manifest=manifest;this.fetcher=fetcher;this.cache=new Map();this.pending=new Map();}
 async load(year){const mapYear=Math.min(this.manifest.to,year),b=binFor(this.manifest,mapYear);if(!b)return null;let bundle=this.cache.get(b.file);if(!bundle){let pending=this.pending.get(b.file);if(!pending){pending=this.fetcher('data/cliopatria/'+b.file).then(r=>{if(!r.ok)throw Error('Territory data unavailable');return r.json();}).then(unpackBundle).then(data=>{this.cache.set(b.file,data);if(this.cache.size>2)this.cache.delete(this.cache.keys().next().value);return data;}).finally(()=>this.pending.delete(b.file));this.pending.set(b.file,pending);}bundle=await pending;}return {type:'FeatureCollection',year:mapYear,features:featuresAt(bundle,mapYear)};}
}
export function searchCatalog(catalog,query,year,nameOf){const q=query.toLocaleLowerCase().trim();if(!q)return [];return catalog.filter(e=>(e.name+' '+nameOf(e.name)).toLocaleLowerCase().includes(q)).map(e=>{const active=e.periods.find(([a,b])=>a<=year&&year<=b),target=active?year:e.periods.reduce((best,[a,b])=>{const y=Math.max(a,Math.min(b,year));return best===null||Math.abs(y-year)<Math.abs(best-year)?y:best;},null);return {...e,target,active:!!active};}).sort((a,b)=>Number(b.active)-Number(a.active)||Math.abs(a.target-year)-Math.abs(b.target-year)).slice(0,60);}
// Undated claims are a general profile, never silently a claim about the selected year.
export function factsForYear(profile,year){if(!profile)return [];return (profile.facts||[]).filter(f=>f.scope==='general'||(f.from??-Infinity)<=year&&year<=(f.to??Infinity));}
